public static async Task<List<Post>> GetPostsByTitlePrefixAsync(
    BlogContext blogContext,
    string prefix,
    CancellationToken cancellationToken)
{
    var postsQuery = from post in blogContext.Posts
                     select post;

    var allPosts = await postsQuery.ToListAsync(cancellationToken);

    // TitleRules.HasPrefix is plain C#, so EF Core cannot translate it to SQL; filter after materializing.
    var matchingPosts = from post in allPosts
                        where TitleRules.HasPrefix(post.Title, prefix)
                        select post;

    return matchingPosts.ToList();
}
