public async Task<Dictionary<int, int>> GetViewsPerBlogAsync(BlogContext context, string searchTerm, CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into g
        select new { BlogId = g.Key, TotalViews = g.Sum(p => p.Views) };

    var totals = await query.ToListAsync(cancellationToken);

    return totals.ToDictionary(t => t.BlogId, t => t.TotalViews);
}
```

