public async Task<Dictionary<int, int>> GetTotalViewsPerBlogAsync(BlogContext blogContext, string searchTerm, CancellationToken cancellationToken)
{
    var postsQuery =
        from post in blogContext.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogGroup
        select new { BlogId = blogGroup.Key, TotalViews = blogGroup.Sum(post => post.Views) };

    var totalViewsPerBlog = await postsQuery.ToListAsync(cancellationToken);

    return totalViewsPerBlog.ToDictionary(blogTotal => blogTotal.BlogId, blogTotal => blogTotal.TotalViews);
}
