public async Task<bool> UpdatePostTitleAsync(BlogContext blogContext, int postId, string newTitle, CancellationToken cancellationToken)
{
    var postQuery =
        from post in blogContext.Posts
        where post.Id == postId
        select post;

    var postToUpdate = await postQuery.FirstOrDefaultAsync(cancellationToken);
    if (postToUpdate is null)
    {
        return false;
    }

    postToUpdate.Title = newTitle;
    await blogContext.SaveChangesAsync(cancellationToken);
    return true;
}
